class ListNode {
  int val;
  ListNode next;

  ListNode(int x) {
    val = x;
  }
}

class Solution {
  public boolean isPalindrome(ListNode head) {
    List<Integer> vals = new ArrayList<>();
    for (ListNode p = head; p != null; p = p.next) vals.add(p.val);
    for (int i = 0, j = vals.size() - 1; i < j; i++, j--) {
      if (!vals.get(i).equals(vals.get(j))) return false;
    }
    return true;
  }
}

class Solution:
    def isPalindrome(self, head: ListNode) -> bool:
        vals = []
        p = head
        while p:
            vals.append(p.val)
            p = p.next
        return vals == vals[::-1]

impl Solution {
  pub fn is_palindrome(head: Option<Box<ListNode>>) -> bool {
    let mut vals = vec![];
    let mut cur = head;
    while let Some(node) = cur {
      vals.push(node.val);
      cur = node.next;
    }
    let mut i = 0;
    let mut j = vals.len() as i32 - 1;
    while i < j {
      if vals[i as usize] != vals[j as usize] {
        return false;
      }
      i += 1;
      j -= 1;
    }
    true
  }
}

const isPalindrome = (head: ListNode | null): boolean => {
  const vals: number[] = [];
  let p = head;
  while (p) {
    vals.push(p.val);
    p = p.next;
  }
  for (let i = 0, j = vals.length - 1; i < j; i++, j--) {
    if (vals[i] !== vals[j]) return false;
  }
  return true;
};
